        graph[s].append(int(a))
    ans = -1
    while graph:
        g = []
        for v in graph:
            if len(graph[v]) == 1:
                heapq.heappush(g, (-int(v, 2), graph[v]))
        if not g:
            ans = 0
            break
        while g and g[0][0] <= n:
            v1, v2 = heapq.heappop(g)
            if v1 + v2 > n:
                ans = max(ans, v1 + v2)
            else:
                if v2 == 0:
                    heapq.heappush(g, (-v2, v1))
                else:
